macro_rules! deps {
    () => {
        Vector!();
    };
}

macro_rules! do_packed_search {
    () => {
        deps!();
        # [doc = " Returns true if the needle has the right characteristics for a vector"] # [doc = " algorithm to handle the entirety of substring search."] # [doc = ""] # [doc = " Vector algorithms can be used for prefilters for other substring search"] # [doc = " algorithms (like Two-Way), but they can also be used for substring search"] # [doc = " on their own. When used for substring search, vector algorithms will"] # [doc = " quickly identify candidate match positions (just like in the prefilter"] # [doc = " case), but instead of returning the candidate position they will try to"] # [doc = " confirm the match themselves. Confirmation happens via `memcmp`. This"] # [doc = " works well for short needles, but can break down when many false candidate"] # [doc = " positions are generated for large needles. Thus, we only permit vector"] # [doc = " algorithms to own substring search when the needle is of a certain length."] # [inline] fn do_packed_search (needle : & [u8]) -> bool { # [doc = " The minimum length of a needle required for this algorithm. The minimum"] # [doc = " is 2 since a length of 1 should just use memchr and a length of 0 isn't"] # [doc = " a case handled by this searcher."] const MIN_LEN : usize = 2 ; # [doc = " The maximum length of a needle required for this algorithm."] # [doc = ""] # [doc = " In reality, there is no hard max here. The code below can handle any"] # [doc = " length needle. (Perhaps that suggests there are missing optimizations.)"] # [doc = " Instead, this is a heuristic and a bound guaranteeing our linear time"] # [doc = " complexity."] # [doc = ""] # [doc = " It is a heuristic because when a candidate match is found, memcmp is"] # [doc = " run. For very large needles with lots of false positives, memcmp can"] # [doc = " make the code run quite slow."] # [doc = ""] # [doc = " It is a bound because the worst case behavior with memcmp is"] # [doc = " multiplicative in the size of the needle and haystack, and we want"] # [doc = " to keep that additive. This bound ensures we still meet that bound"] # [doc = " theoretically, since it's just a constant. We aren't acting in bad"] # [doc = " faith here, memcmp on tiny needles is so fast that even in pathological"] # [doc = " cases (see pathological vector benchmarks), this is still just as fast"] # [doc = " or faster in practice."] # [doc = ""] # [doc = " This specific number was chosen by tweaking a bit and running"] # [doc = " benchmarks. The rare-medium-needle, for example, gets about 5% faster"] # [doc = " by using this algorithm instead of a prefilter-accelerated Two-Way."] # [doc = " There's also a theoretical desire to keep this number reasonably"] # [doc = " low, to mitigate the impact of pathological cases. I did try 64, and"] # [doc = " some benchmarks got a little better, and others (particularly the"] # [doc = " pathological ones), got a lot worse. So... 32 it is?"] const MAX_LEN : usize = 32 ; MIN_LEN <= needle . len () && needle . len () <= MAX_LEN }
    };
}

do_packed_search!()